using LittleLeo;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "CompanionScrappingAction", menuName = "Data/Battle/Battle Actions/Hevelius/CompanionScrapping Action")]
public class CompanionScrappingAction : BattleAction
{
	[Header("Sacrifice Companion Action")]
	[SerializeField]
	private CurrentCompanions currentCompanions;

	[SerializeField]
	protected BattleAction battleAction;

	[SerializeField]
	private OmenLogic omenLogic;

	[SerializeField]
	private bool useCompanionCurrentCorruptionAsAmount;

	[SerializeField]
	private bool energizedScrapping;

	[SerializeField]
	private bool restorePreviousEffects;

	public BattleAction BattleAction => battleAction;

	public bool EnergizedScrapping => energizedScrapping;

	public override bool CheckConditionToBeCasted(bool playerHand, DiceOwnerEnum diceOwnerEnum)
	{
		return IsAnyCompanionAlive();
	}

	protected bool IsAnyCompanionAlive()
	{
		return currentCompanions.ActiveCompanions.Count > 0;
	}

	public override void CastTargetAmount(GameObject target, int amount, GameObject source)
	{
		ReferenceSingleton<GameStateManager>.Instance.SetState(ReferenceSingleton<GameStateManager>.Instance.NoInteractionState);
		if (restorePreviousEffects)
		{
			target.GetComponent<CompanionEffects>().SetNextTimeRepairedRestorePreviousEffects(value: true);
		}
		ReferenceSingleton<HeveliusOmensHandler>.Instance.OnSentinelsCorruptedActivateShiningApparatus(target);
		CompanionCorruptionStats component = target.GetComponent<CompanionCorruptionStats>();
		if (useCompanionCurrentCorruptionAsAmount)
		{
			amount *= (int)component.MaxCorruption - (int)component.CurrentCorruption;
		}
		component.InstantlyDefeatCompanionScrapping(this);
		InvokeAlternatives.InvokeAfterMultipleFrames(ReferenceSingleton<CoroutineHandler>.Instance, ReferenceSingleton<BattleHandler>.Instance.FramesToWaitToUpdateCorruption + 1, delegate
		{
			omenLogic.ActivateOmen(battleAction, amount, target, source);
			CheckCancelAutoOnDiceCastedOnRuneCasted(source);
		});
	}

	public override void CastTarget(GameObject target, GameObject source)
	{
		ReferenceSingleton<GameStateManager>.Instance.SetState(ReferenceSingleton<GameStateManager>.Instance.NoInteractionState);
		ReferenceSingleton<HeveliusOmensHandler>.Instance.OnSentinelsCorruptedActivateShiningApparatus(target);
		CompanionCorruptionStats component = target.GetComponent<CompanionCorruptionStats>();
		int actionValue = EffectsValues.NO_VALUE;
		if (useCompanionCurrentCorruptionAsAmount)
		{
			actionValue = (int)component.MaxCorruption - (int)component.CurrentCorruption;
		}
		component.InstantlyDefeatCompanionScrapping(this);
		InvokeAlternatives.InvokeAfterMultipleFrames(ReferenceSingleton<CoroutineHandler>.Instance, ReferenceSingleton<BattleHandler>.Instance.FramesToWaitToUpdateCorruption + 1, delegate
		{
			omenLogic.ActivateOmen(battleAction, actionValue, target, source);
			CheckCancelAutoOnDiceCastedOnRuneCasted(source);
		});
	}

	public void SpawnScrappingVFX(GameObject target)
	{
		if (IsVFXEnabled())
		{
			PlaySFX();
		}
		SpawnVFX(GetVFXOwnerPosition(target), 4f);
	}
}
